flow.set('current_hvac', '', 'default');

msg.payload = '';
msg.class = '';
msg.enabled = true;
msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'name'
}];

let i = 1;
let names = global.get('hvac', 'default');
if (typeof names === 'object') {
    for(const name in names) {
        msg.options[i++] = {
            'label':name,
            'value':name,
            'dropdown':'plant'
        }
    }
}

return msg;
